// Forge Character Builder — prompt helpers for txt2img / img2img.
// Only the fragment generated by this extension is touched; the existing
// prompt (LoRA, weights, BREAK, ...) is never rewritten.

function computeCharacterBuilderAppend(current, fragment, lastAppended) {
    const text = String(current || "");
    const piece = String(fragment || "").trim();
    if (!piece) {
        return { text: text, changed: false, status: "Nothing to append" };
    }

    const trimmed = text.replace(/\s+$/, "");
    if (lastAppended && piece === lastAppended && trimmed.endsWith(piece)) {
        return { text: text, changed: false, status: "Already appended" };
    }

    if (!trimmed) {
        return { text: piece, changed: true, status: "Prompt appended" };
    }
    const separator = trimmed.endsWith(",") ? " " : ", ";
    return { text: trimmed + separator + piece, changed: true, status: "Prompt appended" };
}

function characterBuilderSwitchTab(tabname) {
    if (tabname === "txt2img" && typeof switch_to_txt2img === "function") {
        switch_to_txt2img();
    } else if (tabname === "img2img" && typeof switch_to_img2img === "function") {
        switch_to_img2img();
    }
}

function appendCharacterBuilderPrompt(text, tabname) {
    const textarea = gradioApp().querySelector(`#${tabname}_prompt textarea`);
    if (!textarea) {
        return `${tabname} prompt box not found`;
    }

    const memory = window.__characterBuilderLastAppended || (window.__characterBuilderLastAppended = {});
    const result = computeCharacterBuilderAppend(textarea.value, text, memory[tabname]);
    if (result.changed) {
        textarea.value = result.text;
        updateInput(textarea);
        memory[tabname] = String(text || "").trim();
    }
    if (result.status !== "Nothing to append") {
        characterBuilderSwitchTab(tabname);
    }
    return result.status;
}

function replaceCharacterBuilderPrompt(text, tabname) {
    const piece = String(text || "").trim();
    if (!piece) {
        return "Nothing to replace with";
    }
    const textarea = gradioApp().querySelector(`#${tabname}_prompt textarea`);
    if (!textarea) {
        return `${tabname} prompt box not found`;
    }
    textarea.value = piece;
    updateInput(textarea);
    const memory = window.__characterBuilderLastAppended || (window.__characterBuilderLastAppended = {});
    memory[tabname] = piece;
    characterBuilderSwitchTab(tabname);
    return "Prompt replaced";
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { computeCharacterBuilderAppend };
}
